public String getShortFileName(String selection) { //get a shortened file name to display in ui
  char[] chars = selection.toCharArray();
  int lastSlash = 0;
  for (int i = 0; i < selection.length(); i ++) {
    if (chars[i] == '/') lastSlash = i;
  }
  String modSelection = selection;
  if (lastSlash != 0) {
    modSelection = "";
    for (int i = lastSlash+1; i < selection.length(); i ++) {
      modSelection += chars[i];
    }
  }
  if (modSelection.length() >= 30){
  char[] modchararr = modSelection.toCharArray();
  String temp = "";
  for (int i = 0; i < 30; i ++) {
    temp += modchararr[i];
  }
  temp += "...";
  modSelection = temp;
  }
  return modSelection;
}

