//ADSR Generation Code
public float[] mapADSR() {
  float attack;
  float decay;
  float sustain;
  float release;
  if (noSliderTouched) {
    attack = 0.5f;
    decay = 0.5f;
    sustain = 0.5f;
    release = 0.5f;
  } else {
    attack = map(sliderVals[0], 0, 10, 0.f, 1.f);
    decay = map(sliderVals[1], 0, 10, 0.f, 1.f);
    sustain = map(sliderVals[2], 0, 10, 0.f, 1.f);
    release = map(sliderVals[3], 0, 10, 0.f, 1.f);
  }
  return new float[]{attack*envMult, decay*envMult, sustain*envMult, release*envMult};
}

public ADSR genADSR(float maxAmp, float attTime, float decTime, float relTime, float susLvl) {
  return new ADSR( maxAmp, attTime, decTime, susLvl, relTime );
}


//Playback Master Function
public void smpl() {
  if (!showPlayLine) {
    noShow = true;
    linecounter = 700;
  } else {
    linecounter = 0;
  }
  if (mode != 4.0f) {
    float[] wav;
    float[] lfo;
    if (clearWav && wavControl) {
      wav = resetSin;
    } else if (!wavControl) {
      wav = defaultWav;
    } else {
      wav = processWavImage();
    }
    if (clearLFO && lfoControl) {
      lfo = invertFlArr(genSinWav());
    } else if (!lfoControl) {
      lfo = invertFlArr(defaultLFO);
    } else {
      lfo = invertFlArr(processLFOImage());
    }
    float[] envVals = mapADSR();
    ADSR env = genADSR(volume, envVals[0], envVals[1], envVals[3], 0.275f);
    float dur = (envVals[2]*envMult) +(envMult);
    float mappedAdj = map(fineAdjust, -20.0f, 20.0f, noteHz[noteIndex-1]+0.5f-noteHz[noteIndex], noteHz[noteIndex+1]-0.5f-noteHz[noteIndex]);
    float freq = (noteHz[noteIndex]+mappedAdj)*oct[octIndex];
    if (recordEnabled) {
      recorder.beginRecord();
    }
    out.playNote( 0.0f, dur, new SmplInstrument(wav, lfo, env, freq));
    if (recordEnabled) {
      wait(9000);
      recorder.endRecord();
      recorder.save();
    }
  } else {
    photowaveformSmpl();
  }
}

//Playback for Photosynthesis Mode
public void photowaveformSmpl() {
  ArrayList<float[]> processed = processMultiImage(imageMode);
  float photoSampleRate;
  if (photoPitch) {
    photoSampleRate = (noteHz[noteIndex]+fineAdjust)/2;
  } else {
    photoSampleRate = (noteHz[7]+fineAdjust)/2;
  }
  if (photsynthesisDots[0] == true) {
    wavR = processed.get(0);
    wavSet[0] = true;
  } else {
    wavSet[0] = false;
  }
  if (photsynthesisDots[2] == true) {
    wavG = processed.get(1);
    wavSet[1] = true;
  } else {
    wavSet[1] = false;
  }
  if (photsynthesisDots[1] == true) {
    wavB = processed.get(2);
    wavSet[2] = true;
  } else {
    wavSet[2] = false;
  }
  if (photsynthesisDots[3] == true) {
    wavY = processed.get(3);
    wavSet[3] = true;
  } else {
    wavSet[3] = false;
  }
  if (photsynthesisDots[4] == true) {
    wavP = processed.get(4);
    wavSet[4] = true;
  } else {
    wavSet[4] = false;
  }
  if (photsynthesisDots[5] == true) {
    wavO = processed.get(5);
    wavSet[5] = true;
  } else {
    wavSet[5] = false;
  }

  float[] envVals = mapADSR();
  ADSR env = genADSR(volume, envVals[0], envVals[1], envVals[3], 0.275f);
  float dur = (envVals[2]*envMult) +(envMult);
  if (recordEnabled) {
    recorder.beginRecord();
  }
  out.playNote( 0.0f, dur, new Photosynthesizer(wavR, wavG, wavB, wavY, wavP, wavO, env, photoSampleRate, freqArrPhotoMode, wavSet));
  if (recordEnabled) {
    wait(9000);
    recorder.endRecord();
    recorder.save();
  }
}
