public float[] invertFlArr(float[] arr) {
  float[] arrCopy = new float[arr.length];
  for (int i = 0; i < arr.length; i ++) {
    arrCopy[i]= -arr[i];
  }
  return arrCopy;
}
Oscil       wave;
Oscil       lfo;
Wavetable   wavtable;
Wavetable   lfotable;
Constant lfoAdd;
class SmplInstrument implements Instrument
{

  ADSR adsr;
  // constructor
  SmplInstrument(float[] wavCapture, float[] lfoCapture, ADSR env, float hz)
  {
    adsr = env;
    // create oscillators of wavtable from float[]
    wavtable = new Wavetable(wavCapture);
    wave  = new Oscil( hz, 0.5f, wavtable );

    if (lfoOn) {
      if(fmOn){
      lfotable = new Wavetable(lfoCapture);
      float freq = map(lfoMods[0], 0.0f, 1.0f, 0.05f, 5.0f);
      float amp = map(lfoMods[2], 0.0f, 1.0f, 000.0f, 400.0f);
      lfoAdd = new Constant(map(lfoMods[1], 0.0f, 1.0f, 300.0f, 400.0f));
      Summer lfoSum = new Summer();
      lfo  = new Oscil(freq, amp, lfotable );
      lfoAdd.patch(lfoSum);
      lfo.patch(lfoSum);
      //send LFO to to Wav
      lfoSum.patch( wave.frequency );
      } else {
      lfotable = new Wavetable(lfoCapture);
      float freq = map(lfoMods[0], 0.0f, 1.0f, 0.05f, 5.0f);
      float amp = lfoMods[2];
      lfo  = new Oscil(freq, amp, lfotable );
      lfo.patch(wave.amplitude);
      }
    }
    //Send Wav to ADSR
    wave.patch( adsr );
  }
  //noteOn and noteOff called when out.playNote() is called
  public void noteOn( float dur )
  {
    adsr.noteOn();
    adsr.patch( out );
  }

  public void noteOff()
  {
    adsr.unpatchAfterRelease( out );
    adsr.noteOff();
    noShow = false;
  }
}
